// El texto del recordatorio. Se arma aqui y no en la base porque es lo que
// lee una persona, y cambiarlo no deberia ser una migracion.
//
// Si el negocio escribio el suyo en la configuracion, se usa ese; si no, uno
// que sirve para cualquier sector — no dice «tu clase» ni «tu tratamiento».
const e = $input.first().json;
const p = e.payload || e;

const nombre = (p.nombre || '').trim().split(/\s+/)[0] || '';
const saludo = nombre ? 'Hola ' + nombre + ', ' : 'Hola, ';

let texto = (p.texto || '').trim();
if (!texto) {
  // La fecha ya viene con punto («10:00 a. m.»), asi que agregar otro deja
  // «a. m..». Se pone solo si hace falta.
  const fecha = String(p.cuando || '').trim();
  texto = saludo + 'te recordamos tu ' + (p.servicio ? p.servicio.toLowerCase() : 'cita') +
          ' el ' + fecha + (/[.!?]$/.test(fecha) ? '' : '.');
  if (p.pedir_confirmacion) {
    texto += ' ¿Nos confirmas si vienes?';
  }
} else {
  // El texto del negocio puede traer marcas; se reemplazan las que tengan
  // sentido y las demas se quitan, para que nadie reciba un {{cuando}} suelto.
  texto = texto
    .replace(/\{\{\s*nombre\s*\}\}/gi, nombre)
    .replace(/\{\{\s*cuando\s*\}\}/gi, p.cuando || '')
    .replace(/\{\{\s*servicio\s*\}\}/gi, p.servicio || '')
    .replace(/\{\{[^}]*\}\}/g, '')
    .replace(/\s{2,}/g, ' ')
    .trim();
}

return [{ json: {
  instance: String(p.instance || ''),
  telefono: String(p.telefono || '').replace(/\D/g, ''),
  company_id: p.company_id,
  cita_id: p.cita_id,
  texto,
  test: !!p.test,
}}];
